                let server=TcpStream::connect("127.0.0.1:55432").await.unwrap();
                let (mut cr,mut cw)=client.into_split(); let (mut sr,mut sw)=server.into_split();
                let outbound=tokio::spawn(async move { let _=tokio::io::copy(&mut cr,&mut sw).await; });
                let mut buf=[0u8;65536];
                loop {
                    let n=sr.read(&mut buf).await.unwrap_or(0); if n==0 {break;}
                    if h.load(Ordering::SeqCst) { b.notify_one(); r.notified().await; }
                    if cw.write_all(&buf[..n]).await.is_err() {break;}
                }
                outbound.abort();
            });
        }
    });
